return {
  [695033351147520] = "Carta da Lula",
  [475127535896064] = "Nome Honorífico",
  [1117310777566208] = "Materiais Internos",
  [634144941970944] = "Livro de astrologia",
  [1117310777580800] = "Guia de roaming para Water Lily Town",
  [1117310777573888] = "Evangelho do Louco",
  [1117310777567744] = "Rei dos Chefs",
  [880023229696512] = "Cano",
  [633321382043392] = "Aos favorecidos da noite de primavera:",
  [634145210397440] = "Encontrei duzentos Espíritos Malignos enquanto pegava um barco, ocupando o local.",
  [634145210398208] = "Cartas de Tarô antigas e sem manutenção; a tinta dos cartões está manchada e o material é cartolina, e não o tradicional linho prensado.",
  [634145210388992] = "<P_Yellow> Membros principais dos \"Servos da Lua\" </> \nCodinome \"Professor\", identidade real desconhecida, paradeiro desconhecido, suspeito de ser o cérebro por trás de todo o plano de sacrifício. rituais.\nCodinome \"Butler\", Sequência 5 do Espreitador de Mistérios Caminho, detentor direto da Coroa do Conhecimento.\nCodinome \"Hyacinth\"...\nCodinome \"Dandelion\"...\nSequênciaCaminho",
  [633389296179712] = "Testemunho de Butler",
  [634145210415104] = "Uma espingarda de cano duplo modificada; Trevor misturou pó de prata que obteve de um Árbitro nas cápsulas - embora ele não saiba o princípio exato, ele diz que essa coisa pode fazer aqueles \"fantoches imortais\" em Rose Paradise realmente sentirem dor.",
  [634145210414848] = "Uma pequena nota manchada de sangue; parece que algo está escrito nele.",
  [634145210414592] = "Para Beyonder \n Somos Guardiões, mas também um grupo de \n pobres coitados lutando constantemente contra o perigo e a loucura. \n \n Lula que adora mergulhar",
  [634145210414336] = "Para o Vidente \n Adivinhação não é onipotente. \n Lula que adora mergulhar",
  [634145210414080] = "Para o Vidente \n Que seu pêndulo sempre aponte na \n direção correta. \n Lula que adora mergulhar",
  [634145210413824] = "Para Bard \n Louvado seja o Sol! \n Lula que adora mergulhar",
  [634145210413568] = "Para Beyonder \n Luz é o significado de tudo! \n Lula que adora mergulhar",
  [634145210413312] = "Para o Espectador \n Um Espectador só pode ser um espectador. \n Lula que adora mergulhar",
  [634145210413056] = "Para Beyonder \n Todos os presentes do destino \n já foram marcados com um preço no escuro. \n Lula que adora mergulhar",
  [634145210412800] = "Para Beyonder \n Que seu futuro seja tão rico quanto o de Audrey. \n Lula que adora mergulhar",
  [634145210412544] = "Para Beyonder \n Sempre há coisas que são mais altas que outras! \n Lula que adora mergulhar",
  [634145210412288] = "Para Beyonder \n Tudo o que for falado, será conhecido. \n Lula que adora mergulhar",
  [634145210412032] = "Ao Aprendiz \n Que cada Porta que você abrir \n traga uma nova surpresa. \n Lula que adora mergulhar",
  [634145210411776] = "Aos favorecidos da Roda da Fortuna \n Que a balança da sorte sempre pline a seu favor. \n Lula que adora mergulhar",
  [634145210411520] = "Para Beyonder \n O Louco que não pertence a esta era, \n o misterioso governante acima da névoa cinzenta, \n o Rei do Amarelo e do Preto que exerce boa sorte. \n Lula que adora mergulhar",
  [634145210411264] = "Para o Guerreiro \n O crepúsculo é o fim do dia, \n o amanhecer é o fim da noite. \n Lula que adora mergulhar",
  [634145210411008] = "Para Aprendiz \n Não se perca. \n Lula que adora mergulhar",
  [634145210410752] = "Para Beyonder \n Não confie no passado, \n não tema o futuro. \n Lula que adora mergulhar",
  [634145210410496] = "Para o jogo \"Lord of Mysteries\" \n Desejamos um beta aberto de sucesso! Que o Sr. \"Tolo\" abençoe \n que a contagem de insetos seja zero, e que o Beyonder possa digerir sua poção sem problemas! \n Lula que adora mergulhar",
  [634145210410240] = "Bem vindo, Beyonder ! \n Desejo a você uma boa digestão de sua poção hoje. \n Lula que adora mergulhar",
  [634145210409984] = "Para Beyonder \n Somos todos prisioneiros da época, \n mas sempre há quem tente dançar na jaula. \n Lula que adora mergulhar",
  [634145210409728] = "Boa sorte \n Navegação tranquila \n Lula que adora mergulhar",
  [634145210409472] = "Para Mystery Pyer \n Faça o que quiser, mas não faça mal. \n Lula que adora mergulhar",
  [634145210408960] = "Uma estranha Flor Comedora de Homens que não mostra agressão; um caderno manchado com ácido é colocado próximo ao pote de alquimia.",
  [633801076115200] = "—Extraído da Coleção de Poesias da Corte, página 1859.\nO ritmo clássico do estilo Roselle expressa vividamente o peso do conhecimento, deixando todos os presentes em silêncio.",
  [634145210408704] = "Benjamin aceitou, mas o que sentiu foi o calor da Rua Cruz de Ferro: cada marca que o velho polia sob a lâmpada continha a obsessão de proteger sua família. Benjamin agarrou-o com força, e o distintivo de repente brilhou com uma luz roxa pálida, um poder quente fluindo em seu sangue - esta é a bênção do vovô Thomas e também a última proteção da Rua Cruz de Ferro.",
  [634145210408448] = "Uma é a origem da contagem. \n \n Infelizmente, também se tornou o fim para esta pessoa falecida; exceto um caderno, todas as informações, incluindo a própria pessoa, foram apagadas pela corrupção nela contida.",
  [634145210408192] = "A luz verde na superfície da Bala é corrupta e maligna, parecendo conter um poder sedutor, mas parece irreal.",
  [634145210407936] = "Um poder quente e sujo surge dentro da bala, o que parece capaz de causar danos a <Hide stylename=\"Transparent\" id=\"#161\"> ？？ </> .",
  [634145210407680] = "Um distintivo requintado, um amuleto feito pelo Velho Thomas para as crianças que ele considera família. Certa vez, ele disse: \"Mesmo o melhor artesanato se desgasta, mas a vontade de proteger não.\"",
  [634145210407424] = "Essas pessoas têm posturas diferentes, mas os cantos da boca estão ligeiramente levantados, suas expressões congeladas \n em um arco quase satisfeito. \n\n Mas todos pararam de respirar e estão mortos há muito tempo.",
  [634145210407168] = "Um relógio de bolso com uma caixa bem conservada.",
  [634145210406912] = "O pavio da vela está úmido e parece incapaz de ser aceso.",
  [634145210406656] = "Páginas com conteúdo quase idêntico, exceto pelas posições ligeiramente diferentes das estrelas em cada ilustração.",
  [634145210406400] = "Um livro de astrologia original manuscrito; os cantos estão enrolados por terem sido folheados muitas vezes e algumas páginas parecem diferentes em espessura, como se estivessem grudadas.",
  [634145210406144] = "Um rótulo amarelado está colado na lateral do frasco, com “Tome uma vez ao dia, não exceda a dose” escrito em loenese puro.",
  [634145210405888] = "A superfície da abóbora tem uma leve pulsação e um suco vermelho escuro escorre levemente do caule.",
  [634145210405632] = "Um aviso de desaparecimento danificado pela água com uma foto desbotada. \n Diz: \"Procurando por meu irmão mais novo, visto pela última vez perto da Fazenda Golden Autumn Lake. Se você tiver alguma pista, entre em contato com Gray Pigeon Inn.\" \n Metade do aviso foi arrancado.",
  [634145210405376] = "O vidro está intacto e a moldura da janela é opaca e resistente, sem sinais de ter sido arrancada ou desmontada. \n Estruturalmente, esta janela não pode ser aberta; é mais como uma janela decorativa usada exclusivamente para iluminação.",
  [634145210405120] = "Seu rosto está pálido e sua expressão está congelada em um estado de espanto e horror. Não há lesões externas óbvias no corpo.",
  [634145210404864] = "O Barão Hawkes caiu ao lado da mesa. \n Seu corpo está caído para frente, sua mão direita ainda mantendo uma postura de alcance, como se estivesse tentando agarrar algo antes de morrer. \n O chá preto no chão está derramado por toda parte.",
  [634145210404608] = "O chá preto é derramado no chão, deixando uma grande quantidade de manchas de água não secas. A xícara de chá foi virada perto do cadáver e uma pequena quantidade de chá preto quente ainda permaneceu na xícara.",
  [634145210404352] = "Sobre a mesa há uma bandeja de prata e um bule combinando; eles devem ser um conjunto com a xícara no chão.",
  [634145210404096] = "Uma pilha de registros médicos está pressionada ao lado do frasco do remédio. \n As páginas estão ligeiramente enroladas, claramente folheadas repetidamente. \n Uma folha de registro está meio exposta, dobrada às pressas, como se alguém a tivesse olhado recentemente e não tivesse tido tempo de guardá-la.",
  [634145210403840] = "Vários frascos de remédios estão espalhados pela mesa. O pequeno e requintado frasco na frente está vazio, com apenas vestígios de resíduos de remédios nas paredes internas.",
  [634145210403584] = "Um caixão de pedra entre escombros e ervas daninhas. \n\n Tem uma longa história e há leves vestígios de intemperismo na superfície.",
  [634145210403328] = "Mentiras não morrem; enquanto houver pessoas que anseiam por respostas simples, voltarei.",
  [634145210403072] = "Artefato Selado Nível 2, uma relíquia do Árbitro Caminho . \n Pode emitir decretos temporários dentro de um intervalo específico, forçando as metas a cumprirem. \n O decreto era originalmente uma algema, mas pelas mãos de um subornador, tornou-se um presente. \n Os crentes pensaram que tinham ganhado proteção, mas a linha vermelha já havia se formado. \n Esta é a fonte do poder do Escudo do Lobo Dourado.",
  [634145210402816] = "As palavras \"Oathbreaker\" podem ser vistas vagamente. É melhor encontrar-se com Trevor primeiro.",
  [634145210402560] = "Uma bala prateada deixada cair por um monstro gigante após sua morte, que parece conter um certo poder mágico em seu interior.",
  [634145210402304] = "Uma mancha escura de sangue que não sai; Não quero me lembrar da cena daquela época.",
  [634145210402048] = "Papel manuscrito da empresa usado; a cópia está um pouco torta.",
  [634145210401792] = "A música favorita de Sally, que ela tocou enquanto ajudava casais a resolver crises de pedidos de casamento no Café\n.",
  [634145210401536] = "Ainda me lembro do sorriso malicioso que Sally exibiu quando o colocou em um lugar de destaque \n.",
  [634145210401280] = "Uma escultura em madeira de um piano que não se parece com um piano.",
  [634145210401024] = "Não tive coragem de olhar de perto, então apenas endireitei um pouco os livros.",
  [634145210400768] = "Depois que Sally adoeceu, muitas vezes me arrependi de não ter estudado medicina antes.",
  [634145210400512] = "Uma linha de pequeno texto está gravada na parte inferior do piano—\n <P_Yellow> \"I saw spring\" </> .",
  [634145210400256] = "Já vi este piano de madeira muitas vezes.",
  [634145210400000] = "Este lado está esculpido com uma flor embaçada.",
  [634145210399744] = "Este lado está esculpido com uma borboleta áspera.",
  [634145210399488] = "Um instrumento musical de madeira feito à mão; a técnica de escultura é desajeitada e pouco refinada.",
  [634145210399232] = "Um espelho de maquilhagem vintage com uma moldura estampada, mas a superfície do espelho é invulgarmente clara - neste Rose Paradise cheio de nevoeiro, é limpo ao ponto de ser abrupto. \n Fraco espiritualidade vaza da borda do quadro, fluindo lentamente como se estivesse vivo...",
  [634145210398976] = "No canto do mercado, debaixo do plátano, uma barraca vazia...",
  [634145210398720] = "A combinação de visco e avelãs não é uma tradição sazonal, mas é aqui colocada independentemente da estação.",
  [634145210398464] = "“Introdução à Astrologia”, “Guia Completo de Quiromancia”, “Aprenda Tarô em Três Dias”; todos são livros de baixa qualidade.",
  [862018190027776] = "Sino",
  [634145210397952] = "Encontrou duzentas sombras negras enquanto caminhava à noite, reivindicando o local.",
  [634145210397696] = "Conheci duzentos tutores de misticismo enquanto frequentava a escola, ocupando a vaga.",
  [862018190124288] = "Quadro de avisos",
  [634145210397184] = "Havia 10 sombras negras flutuando nas casas de 5 pessoas às 9h,\n e elas não se espalharam até as 6h03:02.\n\n As sombras negras são as donas do dia.",
  [634145210396928] = "Durante o dia, 11 tutores de misticismo se teletransportaram para 6 locais no antigo castelo às 13h00, \n e não retornaram para a Cidade Pequena até as 8h10min03s do dia seguinte. \n\n Trabalhando como professor de misticismo em Ramde durante o dia.",
  [634145210396672] = "Durante o dia, 8 Espíritos Malignos foram para 6 locais no antigo castelo às 7h01, \n e não retornaram para a Cidade Pequena até 11h10min15s. \n\n Os Espíritos Malignos realmente apareceram durante o dia.",
  [634145210396416] = "\"26 de maio, eu gosto bastante do status de 'Savant'. Estranhamente, quando me identifico como um 'Savant' e faço coisas consistentes com isso, os sussurros que me enlouquecem diminuíram um pouco. É esta a <P_Yellow> 'Atuação' </> que o Sr. Zarathul mencionou? Esta pode ser a chave para resolver os perigos ocultos das poções. \"",
  [634145210396160] = "Depois que Klein terminou rapidamente de ler uma página, ele voltou seu olhar para o final. \n \"2 de outubro, eles decidiram me deixar noivo de Matilda da família Abel! Não, devo resistir a esse casamento arranjado!\" \n \"5 de outubro, Srta. Matilda está realmente linda.\"",
  [634145210395904] = "\"No dia 8 de abril, fiquei na proa do Trono Negro e disse a Green e Edwards: 'Querem meu tesouro? Vá procurá-lo no final do Mar Nevoeiro!'\"",
  [634145210395648] = "Um nome está escrito torto no balcão de registro na parte de trás,\n \"Lydia\".",
  [634145210395392] = "A ferrugem é muito uniforme, como se tivesse sido envelhecida deliberadamente.",
  [634145210395136] = "<P_Yellow> Você mudou de ideia de repente </> . \nTalvez tenha sido porque você não obteve permissão para acariciá-lo, talvez porque ele estava muito absorto, ou talvez tenha sido apenas porque de repente você sentiu o cheiro de grãos de café - quente, rico, reconfortante, com uma pitada de vento úmido depois da chuva; seria aquele o cheiro de Tingen do lado de fora da Porta? \n\nVocê não parece mais se importar tanto com a sensação de seu pelo.",
  [634145210394880] = "Um lindo cachorro golden retriever, lendo um livro muito a sério.",
  [634145210394624] = "Alguns arranhões leves, como marcas deixadas pela fricção com a pele após uso prolongado, como se ainda restasse algum tipo de coisa do proprietário anterior.",
  [634145210394368] = "Um emblema com um design simples e elegante. Este é o símbolo de status para membros de alto nível do Rose Paradise; possuí-lo abrirá qualquer área da boate para você.",
  [634145210394112] = "Estranhamente, o material do interior da máscara parece mais quente do que o exterior, tal como... a temperatura corporal deixada por alguém que a usa há muito tempo.",
  [634145210393856] = "Uma requintada máscara de porcelana branca sem expressão. A parte superior é incrustada com padrões dourados claros que apresentam uma textura sutil ao toque. Este é o passe de admissão para Rose Paradise – somente usando-o você poderá realmente “ver” o mundo atrás da Porta.",
  [634145210393600] = "Albert está parado na beira do salão, seu corpo tremendo levemente enquanto ele levanta os óculos na ponta do nariz. \n\n\n Sob a luz, as lentes refratam um brilho incomum, como se não fossem \n vidro comum.",
  [634145210393344] = "William Haywood, o anfitrião deste baile, não parece ser um \n verdadeiro anfitrião. Seu rosto, de trinta e poucos anos, deveria ser imponente, \n mas há uma leve camada de exaustão entre suas sobrancelhas. \n Seus olhos ocasionalmente examinam uma determinada direção - não olhando para as pessoas, mas como se \n confirmassem algo.",
  [634145210393088] = "Mas abaixo do anel, uma ponta de agulha muito fina é vagamente visível, brilhando sob a luz\n.",
  [634145210392832] = "Ela é sem dúvida a pessoa mais atraente da sala. Suas feições são tão lindas que são quase \n irreais, e seus olhos verde-acinzentados carregam um distanciamento casual \n - como se ela estivesse gostando do baile, mas também observando todos friamente do lado de fora. \n",
  [634145210392576] = "Ao lado está o \"Loen Psychological Society Monthly\", com o artigo de capa intitulado \n \"Sonhos e o Subconsciente: Uma Revisão de Pesquisas Recentes\".",
  [634145210392320] = "Uma publicação - \"Revisão Psiquiátrica\". A página aberta \n apresenta um artigo sobre \"Perda de Memória Traumática\", com vincos de leitura nas bordas \n. \n\n Ao lado está o \"Loen Psychological Society Monthly\", com o artigo de capa intitulado \n \"Sonhos e o Subconsciente: Uma Revisão de Pesquisas Recentes\".",
  [634145210392064] = "Uma arma velha vendida no mercado, parece um pouco enferrujada.",
  [634145210391808] = "O cano da arma está um pouco enferrujado, mas isso não afetará o disparo da bala.",
  [634145210391552] = "A mola dentro do gatilho está torta; basta ajustá-lo.",
  [634145210391296] = "Um pequeno aviso está impresso no canto inferior direito: \"Este produto não tem relação com\n 'O Grande Aventureiro'.\"",
  [634145210391040] = "A lata é impressa com um padrão de comida enlatada de peixe-lobo, rotulada como \"escolha de Gehrman \n.\".",
  [634145210390784] = "Um jovem enrolado na esquina, aparentemente escondendo algum segredo...",
  [634145210390528] = "Mãos magras manchadas de pó de carvão, recém-saídas da fábrica, com escassos rendimentos e sofrendo de desnutrição.",
  [634145210390272] = "As órbitas oculares do jovem são escuras e azuis; recentemente, há algum tempo, ele está em estado de insônia grave.",
  [634145210390016] = "Grande quantidade de fragmentos de vidro, emitindo forte cheiro de álcool.",
  [827108427320576] = "Registro de transação",
  [634145210388224] = "Localizada nos subúrbios de Tingen, um dos territórios do falecido Visconde Everly. A atual proprietária é a Viscondessa Helena...\nFechado desde abril deste ano por motivos desconhecidos, suspeito de envolver o jovem Visconde ▇▇▇▇▇▇...\n...\nO número de pessoas desaparecidas aumentou e as investigações ligam todas elas ao feudo...\n...\nCorrupção não identificada detectada, aumentando continuamente...\n...\nA A mansão foi confirmada como uma das fortalezas dos Servos da Lua...\n...\nA mansão sofreu uma estranha mutação, situação desconhecida...\n...",
  [634145210387968] = "<P_Yellow> Artefato Selado · Coroa do Conhecimento </> \n\n <P_Yellow> Nível </> \nNível 0\n <P_Yellow> Caminho </> \nEspreitador de Mistérios\n <P_Yellow> Origem </> \nUma relíquia formada depois que o Imperador Roselle foi assassinado em White Maple Palácio, combinando a característica não expulsa do Imperador do Conhecimento dentro de seu corpo com sua coroa. Contém a corrupção da ▇▇ Deusa Mãe. \n\n <P_Yellow> Efeitos Positivos </> \nMaterializa o conhecimento, capaz de desintegrar objetos físicos em uma Torrente de Conhecimento.\nConcede conhecimento da maioria dos assuntos e permite a interpretação direta de informações ocultas (incluindo os segredos das divindades).\nFornece compreensão de verdades cósmicas e essências místicas que transcendem Sequências.\nPode emitir comandos para Controle Mental e cognitivo. reestruturação para aqueles de um nível inferior Sequência . \n\n <P_Yellow> Efeitos Negativos </> \nA coroa instila continuamente uma quantidade insuportável de verdade e Conhecimento Proibido; interpretar esse conhecimento resulta em uma perda aleatória de sanidade ou personalidade.\nRemover a coroa desencadeia uma reação da Torrente de Conhecimento, destruindo instantaneamente a alma do portador e deixando-o como uma concha vazia e ignorante.\n\n <P_Yellow> Artefato Selado · Espelho Mágico do Desespero </> \n\n <P_Yellow> Nível </> \nDesconhecido, Sem classificação\n <P_Yellow> Caminho </> \nAssassino\n <P_Yellow> Origem </> \nFormado quando a Bruxa do Desespero Helga falhou em seu avanço para Sequência 3 e perdeu o controle. Para evitar que ela se transformasse totalmente em um monstro, a Viscondessa acabou com sua vida pessoalmente. O restante Característica de Beyonder combinado com um espelho e mutado. Helga e a Viscondessa foram amigas íntimas durante a vida de Helga. Sua vontade residual combinada com a característica para formar este Artefato Selado.\n\n <P_Yellow> Efeitos Positivos </> \nCapaz de construir um mundo espelhado independente.\nPossui habilidades de selamento de consciência, capaz de segmentar e selar espíritos poderosos ou vontades divinas.\n\n <P_Yellow> Efeitos Negativos </> \nPossui uma forte consciência autodestrutiva e tendências misantrópicas; isso induzirá criaturas próximas a destruir o espelho mágico. Se a superfície do espelho se quebrar, ela provoca uma violenta reação espiritual.\nAbsorve indiscriminadamente a esperança e as emoções das formas de vida circundantes, convertendo-as em nutrientes para sustentar o mundo do espelho. As criaturas dentro do alcance gradualmente se sentirão vazias e entorpecidas, eventualmente caminhando em direção à autodestruição.",
  [634145210387712] = "“Grande Mãe”, agora confirmado como avatar de ▇▇▇▇, símbolo da reprodução e fertilidade, dominando a concepção da vida e a proliferação da carne e do sangue, ocupando a autoridade ▇▇▇▇. As organizações que acreditam nela incluem a ▇▇ Mãe, a Escola de Pensamento Rosa e a Lua Primordial.\nOrar a Ela concederá uma capacidade reprodutiva vigorosa, mas a pessoa gradualmente perderá sua sanidade, se tornará fanática, buscará os tabus da vida e a essência de espiritualidade, e cairá no desejo de nascimento e reprodução...\nO ritual secreto de sacrifício requer uma grande quantidade de carne, sangue e vida, e o processo é acompanhado por extrema loucura e caos...\nDurante a crise de Tingen, o Servo da Lua sacrificou a cidade inteira como preço para criar um navio para a descida da descendência do deus do mal, provocando uma catástrofe devastadora...",
  [634145210387456] = "<P_Yellow> Nível de segurança </> Confidencial \n <P_Yellow> Repórter </> Leonard Mitchell \n <P_Yellow> Data </> julho de 1354 \n\n <P_Yellow> Visão geral do evento </> \n Desde junho de 1354, uma série de casos bizarros de desaparecimento de cidadãos ocorreram em Tingen. Depois que a Blackthorn Security Company interveio na investigação, foi confirmado que havia uma intervenção de poder oculta por trás dos eventos, e foi finalmente confirmado ser um Ritual de Sacrifício em grande escala planejado pela organização do deus maligno \"Moon Servant\". Seu objetivo era usar a Coroa do Conhecimento e o Espelho Mágico do Desespero para sacrificar a cidade inteira à \"Grande Mãe\" (confirmada como sendo o avatar de ▇▇▇▇) para dar à luz a descendência do deus do mal. estudantes, etc. \n A maioria das pessoas desaparecidas recentemente entrou em contato com itens relacionados ao Imperador Roselle, incluindo espelhos de festivais de teatro, pôsteres e materiais promocionais. \n Algumas das pessoas desaparecidas participaram do recrutamento de empregos de curto prazo e bem remunerados em May Manor antes de desaparecerem. \n\n <P_Yellow> Situação de resgate e vítimas </> \n Lista de resgate \n... Charlie... Jenny... Lydia... Jack... \n Lista de vítimas \n... Karl... Johnson... Joan... \n\n <P_Yellow> Facções relacionadas </> \n Moon Servant (veja o Relatório de Investigação do Moon Servant para obter detalhes) \n\n <P_Yellow> Artefatos Selados Relacionados </> \n Coroa do Conhecimento \n Espelho Mágico do Desespero<P_Yellow></>\n\n\nBeyonder",
  [634145210387200] = "<P_Yellow> May Manor, trabalho de curto prazo bem remunerado </> \n\n <P_Yellow> Responsabilidades do trabalho </> Após um treinamento simples em May Manor, podar macieiras. \n\n <P_Yellow> Requisitos Básicos </> \n Sem limite de idade, trabalhador, responsável, deve aceitar turnos noturnos. \n <P_Yellow> Jornada de Trabalho </> \n Jornada de trabalho não inferior a 14 horas por dia, por um período de duas semanas. \n <P_Yellow> Salário e Benefícios </> \n Alimentação, acomodação e roupas de trabalho fornecidas, salário semanal de quatro libras, podem ser pagos antecipadamente.",
  [634145210386944] = "Uma vela mística usada em um ritual suicida, com serpente emplumada e decorações de mortos-vivos no castiçal.",
  [634145210386688] = "Um espelho de bronze comum, pequeno em tamanho, novo e requintado, muito adequado como espelho de maquiagem portátil.",
  [634145210386432] = "Uma arma comum em brigas de gangues; seu dono pode querer usá-lo para autodefesa, mas o poder de Tingen espelhada não pode ser combatido por balas.",
  [634145210386176] = "Arma de serviço de um policial de Tingen, o carregador está vazio; seu dono deve ter passado por uma batalha feroz.",
  [634145210385920] = "Fragmentos de um espelho de bronze, que parece prever o caos e a morte do titular.",
  [634145210385664] = "Uma maçã mágica cujo estado muda constantemente, de podre para fresca, e depois de fresca para podre...",
  [634145210385408] = "Folheto de inscrição para escola noturna, com o slogan:\n \"Aula de alfabetização! Frequente a escola noturna! Tenha conhecimento! Tenha futuro!\"",
  [634145210385152] = "<P_Yellow> —\"Aqui jaz o filho mais velho do primeiro Barão Lamud, um cavaleiro, um homem corajoso que não temia a morte.\" </>",
  [634145210384896] = "\"Em homenagem ao grande Imperador Roselle, ele é verdadeiramente o protagonista daquela época -\"\n\"Pioneiro em rotas marítimas seguras no Mar Berserk, abrindo a era do comércio marítimo com o Continente Sul.\"\n\"Melhorando a artilharia, os navios à vela, a fabricação de papel e a impressão... e até mesmo inventando o jornal.\"",
  [634145210384640] = "No mar revolto, um enorme veleiro rompe as ondas e navega em frente. \n O Imperador Roselle está no convés, olhando para longe, com quatro canhões de cada lado.",
  [634145210384384] = "Um selo de longa distância no valor de 5 centavos, com uma locomotiva a vapor como imagem principal. \n O Imperador Roselle fica de lado, aparentemente olhando para a fumaça que sai da chaminé.",
  [634145210384128] = "\"Em 1173, ele derrubou o governo do rei e se tornou o primeiro cônsul da República Intis.\"\n\"Em 1192, ele transformou a República Intis em um império, ascendeu ao trono e proclamou-se Imperador César.\"",
  [634145210383872] = "Um pôster promocional, a figura na foto não é outro senão o Imperador Roselle.\n Ele usa uma coroa, segura um cetro e caminha em direção ao trono no topo da escada.",
  [634145210383616] = "É uma forma oval muito padrão, arredondada na extremidade romba e ligeiramente pontiaguda na extremidade afiada... <P_Heart> (...é a mesma coisa também!) </>",
  [634145210383360] = "A casca do ovo é marrom clara, de cor uniforme e a superfície também é lisa.\n <P_Heart> (A textura também é quase a mesma...) </> \n É uma forma oval padrão, arredondada na extremidade romba e ligeiramente pontiaguda na extremidade afiada.\n <P_Heart> (...é a mesma coisa também!) </>",
  [634145210383104] = "Aproximando-se, sente-se um leve aroma calcário, misturado com um traço de calor próprio dos ovos de aves\n, levemente suspeito. <P_Heart> (Uh, o cheiro é o mesmo.) </>",
  [634145210382848] = "É uma forma oval padrão, arredondada na extremidade romba e ligeiramente pontiaguda na extremidade pontiaguda.",
  [634145210382592] = "A casca do ovo é marrom clara, de cor uniforme e lisa na superfície.\n É um formato oval padrão, arredondado na extremidade romba e ligeiramente pontiagudo na extremidade pontiaguda.",
  [634145210382336] = "Aproximando-se, sente-se um leve aroma calcário, misturado com um traço de calor peculiar aos ovos de aves\n, levemente suspeito.",
  [634145210382080] = "<P_Red> \"Mãe\" </>",
  [634145210381824] = "Uma pedra comum, não diferente das pedras usadas para construir o altar.",
  [634145210381568] = "Enterrado ao lado da estátua de pedra, ainda chamada de \"Recém-nascido\"; o que exatamente isso\n significa?",
  [634145210381312] = "Um objeto esférico retorcido está exposto no caixão de pedra, enrolado por vinhas marrons nuas, como uma semente estranha com um núcleo podre.\n\n",
  [634145210381056] = "Embora Klein ache que esse garotinho se parece mais com uma tartaruga, ele ainda faz careta e explica: “Olhando de perto, é mesmo uma boneca!\n",
  [634145210380800] = "A produção e o design da boneca foram feitos com cuidado; as bordas são polidas e há um pequeno mecanismo de relógio na lateral.\n Klein pergunta com um sorriso: \"Isso é uma tartaruga, certo?\"\n A voz de Melissa soa vagarosamente: \"É uma boneca.\"",
  [634145210380032] = "Um cachimbo com sinais evidentes de uso, mas que não deveria ser usado há muito tempo.\n O cachimbo está exposto na estante e a área ao redor é bem limpa... De quem seria esse cachimbo?",
  [634145210379776] = "Uma campainha colocada na recepção do Blackthorn, conectada a uma corda. \n Não se sabe para onde leva a corda ou qual é sua finalidade.",
  [634145210379520] = "Obteve o machado.",
  [634145210379264] = "Um machado de cabo longo, sua própria existência é um mistério desconhecido,\n talvez ele possa <P_Yellow> abrir </> aquelas coisas difíceis.",
  [634145210379008] = "Obteve a adaga.",
  [634145210378752] = "A adaga inserida no centro do altar circular parece afiada o suficiente,\n deve ser capaz de cortar certos itens.",
  [634145210378496] = "Olhando para a “concha” redonda em suas costas, Klein fica um tanto hesitante.\n “Isso... isso é uma tartaruga, certo?”",
  [634145210378240] = "As bordas da boneca são polidas suavemente e há um pequeno mecanismo de relógio.\n Klein tem algumas suposições, mas não tem certeza.\n \"Isso é uma boneca?\"",
  [634145210377984] = "Um item montado com engrenagens, ferro enferrujado e molas.",
  [634145210377728] = "A capa do caderno é feita inteiramente de papel duro preto profundo, exalando uma aura antiga\n e distante, sem sinais de amolecimento ou decadência.\n\n O cartão da Lua Vermelha enfiado entre as páginas já foi tirado.",
  [634145210377472] = "A capa do caderno é feita inteiramente de papel duro preto profundo, exalando uma aura antiga e distante, sem nenhum sinal de amolecimento ou deterioração.\n\n\n Uma dor de cabeça repentina e intensa surge, como se fosse um aviso perigoso das profundezas de sua memória, impedindo você de abrir este caderno.\n\n\n Você descobre que algo parece estar escondido entre as páginas.",
  [533127042698240] = "Mansão de Maio",
  [634145210377216] = "Encontre o objeto da profecia, vislumbre a verdade e escape do pesadelo—\n <P_Yellow> Um objeto escondido, o som do cordeiro voltando para casa não toca mais. </> \n <P_Yellow> Um objeto armazenado, a semente do renascimento, enterrado ao lado da estátua de pedra. </> \n <P_Yellow> Um objeto escondido, o luar carmesim brilha sobre ele. </> \n...\n...\nO renascido, renascido novamente.\nDécima nona vez, {{ele|ela}} morreu no sonho dezenove vezes.\nDesta vez é o vigésimo pesadelo de {{ele|ela}}.\n{{ele|ela}} abre o Caderno Antígono, que não deveria ter aparecido aqui. morre pela perda de controle causada pelo poder do caderno.\nO renascido, renasce novamente.\nDesta vez é o vigésimo primeiro pesadelo de {{ele|ela}}.\n...\nO renascido vê o Caderno Antígono novamente.\n{{ele|ela}} não abre o caderno, mas compra uma carta ⬛⬛ em vez disso.\n...\nO renascido chega ao altar cheio de flores e decide fazer algo.\nUm forte desejo de compreender a verdade surge no coração do renascido.\n{{ele|ela}} observa o altar e obtém um pedaço de pergaminho contendo a profecia.\nO renascido seguirá a revelação da profecia...\n",
  [634145210376960] = "Debaixo do boneco está um pedaço de pergaminho amarelado, revelando\n algumas linhas de caligrafia obscura.",
  [634145210376704] = "Em frente a um estande cheio de flores silvestres está um boneco magro,\n cercado por três áreas circulares, lindas, mas misteriosas.",
  [634145210376192] = "De acordo com a profecia no pergaminho, coloque o <P_Yellow> objeto da profecia </> no altar.\n \"Um objeto escondido, o luar carmesim brilha sobre ele.\"",
  [634145210375680] = "De acordo com a profecia no pergaminho, coloque o <P_Yellow> objeto da profecia </> no altar.\n \"Um objeto armazenado, a semente de uma nova vida, enterrado ao lado da estátua de pedra.\"",
  [634145210375424] = "O altar mudou...",
  [634145210375168] = "De acordo com a profecia no pergaminho, coloque o <P_Yellow> objeto da profecia </> no altar.\n \"Um objeto escondido, o som do cordeiro voltando para casa não toca mais.\"",
  [634145210374912] = "Um chapéu de criança de antigamente.\n Embora o tecido seja comum, os pontos são finos e bem cuidados, como se tivesse sido mantido bem conservado por alguma\n obsessão.",
  [634145210374656] = "Um espelho velho e desgastado.\n A superfície está quase totalmente obscurecida por manchas, não sendo mais capaz de refletir o rosto do observador.\n",
  [634145210374400] = "Uma panela com uma deliciosa sopa de cogumelos.\n Ela borbulha e sibila, fumegando com o calor e emitindo uma fragrância estranha.",
  [634145210374144] = "Caracteres profundos e superficiais estão esculpidos no tronco da árvore, com muitas\n marcas de registro riscadas ao lado deles, lembrando uma runa ritual inacabada.\n\n <P_Yellow> \"Abra o caderno.\" </> \n\n No entanto, os caracteres foram repetidamente riscados.",
  [634145210373888] = "<P_Yellow> \"Abra o bloco de notas.\" </>",
  [634145210373632] = "Caracteres profundos e superficiais são esculpidos no tronco da árvore, com muitas\n marcas de registro riscadas ao lado deles, lembrando uma runa ritual inacabada.\n\n <P_Yellow> \"Abra o caderno\" </>",
  [634145210373376] = "Uma boneca de cordeiro esfarrapada, o fio em suas costuras <P_Yellow></> parece um selo fechado, esperando por uma lâmina afiada\n <P_Yellow></> para cortar a verdade.\n\n A barriga do cordeiro foi cortada, revelando um brilho de metal.\n\n Obtido <P_Yellow> Sino </> .",
  [634145210373120] = "Uma boneca de cordeiro desgastada. O <P_Yellow> fio </> nas costuras parece um selo fechado, esperando por uma <P_Yellow> lâmina afiada </> para abrir a verdade. \n\nA barriga do cordeiro foi aberta, revelando um brilho de metal.\n",
  [634145210372864] = "Uma boneca de cordeiro desgastada. O <P_Yellow> fio </> nas costuras parece um selo fechado, esperando por uma <P_Yellow> lâmina afiada </> para abrir a verdade.\n",
  [634145210372608] = "A carta da Lua Vermelha colocada no altar.\n\n Um companheiro do Sr. Louco usou esta carta segura para trocar\n por aquela perigosa carta da Lua Vermelha.",
  [634145210372352] = "A carta da Lua Vermelha colocada no altar.",
  [634145210372096] = "Parece haver um objeto estranho costurado dentro de sua barriga; talvez <P_Yellow> uma lâmina afiada </> pudesse cortar o fio costurado\n.",
  [634145210371840] = "Uma boneca de cordeiro desgastada.",
  [634145210371584] = "A capa do caderno é feita inteiramente de papel duro preto profundo, exalando uma aura antiga e distante, sem nenhum sinal de amolecimento ou deterioração.\n\n\n Uma dor de cabeça repentina e intensa surge, como se fosse um aviso perigoso das profundezas de sua memória, impedindo você de abrir este caderno.\n\n\n O cartão retirado do caderno apresenta uma lua cheia carmesim, emitindo um luar misterioso.",
  [634145210371328] = "<P_Red> Você abre o caderno... </>",
  [634145210371072] = "A capa do caderno é feita inteiramente de papel duro preto profundo, exalando uma aura antiga\n e distante, sem nenhum sinal de amolecimento ou decadência.",
  [634145210370816] = "Um cartão de felicitações com um bolo de aniversário desenhado, com uma linha de desejos de aniversário\n escrita nele, como um código secreto ainda a ser falado.\n\n ' <P_Yellow> Feliz Aniversário </>, cresça saudável - Amor, seu irmão.'",
  [634145210370560] = "No verso do cartão, palavras vermelhas brilhantes estão escritas em Hermes:\n <P_Red> \"Pesadelo! Recuse... escape! Recuse... escape...\" </>",
  [634145210370304] = "Um cartão de felicitações com um bolo de aniversário desenhado, com uma linha de \n bênçãos de aniversário escritas nele, como um código secreto que ainda não foi falado.\n\n\" <P_Yellow> Feliz Aniversário </>, cresça saudável - Amor, seu irmão.\"\n\nNo verso do cartão, palavras vermelhas brilhantes estão escritas em Hermes:\n <P_Red> \"Pesadelo! Recusar... escapar! Recusar... escapar...\" </>",
  [634145210370048] = "Um cartão de felicitações com um bolo de aniversário desenhado, com uma linha de desejos de aniversário\n escrita nele, como um código secreto ainda a ser falado.",
